import sqlite3, json
con = sqlite3.connect(r"C:\Users\Administrator\.openviking\data\_system\usage_audit\usage_audit.sqlite3")
tables = [r[0] for r in con.execute("select name from sqlite_master where type='table'")]
print("TABLES:", tables)
for t in tables:
    cols = [c[1] for c in con.execute(f"pragma table_info({t})")]
    n = con.execute(f"select count(*) from {t}").fetchone()[0]
    print(f"\n== {t} ({n} rows) cols={cols}")
    # last-2-days snapshot for the interesting tables
    if t in ("request_audit","usage_retrieval_hourly","usage_vlm_hourly","usage_vlm_daily"):
        try:
            for row in con.execute(f"select * from {t} order by rowid desc limit 30"):
                print(row)
        except Exception as e:
            print("ERR", e)
